<button type="button" class="theme-btn" id="themeBtn" aria-label="Alternar tema claro/escuro" title="Alternar tema"><i class="bi bi-moon-stars"></i></button>
<script>(function(){var b=document.getElementById('themeBtn');if(!b)return;function cur(){return document.documentElement.getAttribute('data-theme')==='dark'?'dark':'light'}function icon(){b.firstElementChild.className='bi '+(cur()==='dark'?'bi-sun':'bi-moon-stars')}icon();b.addEventListener('click',function(){var n=cur()==='dark'?'light':'dark',d=document.documentElement;d.setAttribute('data-theme',n);d.setAttribute('data-bs-theme',n);try{localStorage.setItem('bf-theme',n)}catch(e){}icon();});})();</script>
